import Image from 'next/image';import {requireVendorManager} from '@/lib/auth/vendor';import {getVendorMedia} from '@/services/vendor-dashboard';import {VendorMediaUpload} from '@/components/vendor-media-library';import {deleteMedia} from '@/app/vendor/actions';import {SubmitButton} from '@/components/vendor-forms';
export default async function MediaPage(){const context=await requireVendorManager();const media=await getVendorMedia(context.userId,context.restaurant!.id);return <><div className="vendor-page-head"><div><p className="section-kicker">Médiathèque</p><h1>Photos</h1><p>Ajoutez une photo une fois, puis réutilisez-la sur vos produits.</p></div><VendorMediaUpload restaurantId={context.restaurant!.id}/></div>{media.length?<section className="vendor-media-grid">{media.map(item=><article key={item.id}><span><Image src={item.publicUrl} alt={item.alt_text||item.file_name} fill sizes="(max-width: 600px) 45vw, 220px"/></span><div><strong>{item.file_name}</strong><small>{item.type}</small><form action={deleteMedia}><input type="hidden" name="media_id" value={item.id}/><SubmitButton className="text-btn danger-link" confirmMessage="Supprimer cette photo ? Elle ne doit plus être utilisée sur un produit.">Supprimer</SubmitButton></form></div></article>)}</section>:<section className="vendor-card vendor-empty"><strong>Aucune photo pour le moment.</strong><p>Ajoutez votre logo, votre couverture ou les photos de vos plats.</p></section>}</>}
